from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN
from typing import List, Union

from pydantic import BaseModel, Field, ValidationError, condecimal, conint, validator


class Line(BaseModel):
    sku: str
    quantity: conint(ge=1)
    unit_price: condecimal(ge=0, max_digits=20, decimal_places=2)

    @validator("unit_price", pre=True)
    def parse_unit_price(cls, v):
        # Accept str/int/float, convert to Decimal with 2 decimals exactly
        try:
            d = Decimal(str(v))
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        # Quantize to 2 decimal places, rounding down to avoid rounding surprises
        d = d.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        if d < 0:
            raise ValueError("unit_price must be >= 0")
        return d


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    class Config:
        # No orm_mode needed here
        arbitrary_types_allowed = True

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v):
        # Accept ISO 8601 string or datetime
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be a valid ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        # Remove microseconds for second precision
        dt = dt.replace(microsecond=0)
        return dt


def export_invoice(data: dict) -> str:
    """
    Validate an invoice dict and return JSON text for the billing API.
    Output JSON includes "number", "issued_at" formatted as YYYY-MM-DDTHH:MM:SSZ in UTC,
    "lines" with "sku", "quantity", "unit_price" as string with 2 decimals,
    and "total" as string with 2 decimals.
    Raises ValueError for invalid input.
    """
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e

    # Compute total as Decimal sum of quantity * unit_price
    total = sum((line.quantity * line.unit_price for line in invoice.lines), Decimal("0.00"))
    # Format total as string with exactly two decimals
    total_str = f"{total:.2f}"

    # Format issued_at as YYYY-MM-DDTHH:MM:SSZ
    issued_at_str = invoice.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Prepare lines with unit_price as string with 2 decimals
    lines_out = []
    for line in invoice.lines:
        lines_out.append({
            "sku": line.sku,
            "quantity": line.quantity,
            "unit_price": f"{line.unit_price:.2f}",
        })

    # Compose output dict
    out = {
        "number": invoice.number,
        "issued_at": issued_at_str,
        "lines": lines_out,
        "total": total_str,
    }

    # Return JSON text
    import json
    return json.dumps(out, separators=(",", ":"))

from pydantic import BaseModel, Field, root_validator, validator, ValidationError
import re


class SignupPayload(BaseModel):
    username: str = Field(..., regex=r"^[a-z0-9_]{3,20}$")
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    @validator("email")
    def email_must_contain_at(cls, v: str) -> str:
        v = v.strip().lower()
        if "@" not in v:
            raise ValueError("email must contain '@'")
        return v

    @validator("phone")
    def normalize_phone(cls, v: str) -> str:
        if not isinstance(v, str):
            raise TypeError("phone must be a string")
        compact = re.sub(r"[\s.\-()]", "", v)
        if not re.fullmatch(r"\+\d{8,15}", compact):
            raise ValueError("invalid phone number")
        return compact

    @root_validator
    def passwords_match(cls, values):
        pw = values.get("password")
        pwc = values.get("password_confirm")
        if pw is not None and pwc is not None and pw != pwc:
            raise ValueError("passwords do not match")
        return values


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload dict using pydantic.

    Returns a dict with keys: username, email (stripped and lowercased), phone (compact form).
    Raises ValueError (ValidationError) on invalid or missing fields.
    """
    validated = SignupPayload.parse_obj(data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }

from __future__ import annotations
from decimal import Decimal, ROUND_DOWN
from datetime import datetime, timezone
from typing import Any, List
from pydantic import BaseModel, Field, ValidationError, model_validator
import json


class Line(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal = Field(alias='unit_price')

    model_config = {
        'populate_by_name': True,
        'extra': 'forbid',
        'from_attributes': True,
    }

    @model_validator(mode='before')
    def coerce_types(cls, values: Any) -> Any:
        q = values.get('quantity')
        if isinstance(q, str):
            try:
                values['quantity'] = int(q)
            except Exception as e:
                raise ValidationError([{
                    'type': 'type_error.integer',
                    'loc': ('quantity',),
                    'msg': 'quantity must be an integer',
                    'input': q,
                }])
        up = values.get('unit_price')
        if isinstance(up, (str, int, float)):
            try:
                # Convert float to str first to avoid float precision issues
                if isinstance(up, float):
                    up = format(up, 'f')
                values['unit_price'] = Decimal(up)
            except Exception as e:
                raise ValidationError([{
                    'type': 'type_error.decimal',
                    'loc': ('unit_price',),
                    'msg': 'unit_price must be a decimal',
                    'input': up,
                }])
        # Validate quantity >= 1 and unit_price >= 0 here to catch early
        q_val = values.get('quantity')
        if not isinstance(q_val, int) or q_val < 1:
            raise ValidationError([{
                'type': 'value_error',
                'loc': ('quantity',),
                'msg': 'quantity must be an integer >= 1',
                'input': q_val,
            }])
        up_val = values.get('unit_price')
        if not isinstance(up_val, Decimal) or up_val < 0:
            raise ValidationError([{
                'type': 'value_error',
                'loc': ('unit_price',),
                'msg': 'unit_price must be a decimal >= 0',
                'input': up_val,
            }])
        return values


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    model_config = {
        'populate_by_name': True,
        'extra': 'forbid',
        'from_attributes': True,
    }

    @model_validator(mode='before')
    def coerce_types(cls, values: Any) -> Any:
        ia = values.get('issued_at')
        if isinstance(ia, str):
            try:
                # parse ISO8601 with optional Z
                if ia.endswith('Z'):
                    ia = ia[:-1] + '+00:00'
                dt = datetime.fromisoformat(ia)
                # If naive, treat as UTC
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                values['issued_at'] = dt
            except Exception as e:
                raise ValidationError([{
                    'type': 'value_error.datetime',
                    'loc': ('issued_at',),
                    'msg': 'issued_at must be a valid ISO8601 datetime',
                    'input': ia,
                }])
        elif isinstance(ia, datetime):
            # If naive, treat as UTC
            if ia.tzinfo is None:
                values['issued_at'] = ia.replace(tzinfo=timezone.utc)
        else:
            raise ValidationError([{
                'type': 'type_error',
                'loc': ('issued_at',),
                'msg': 'issued_at must be a datetime or ISO8601 string',
                'input': ia,
            }])
        return values


def export_invoice(data: dict) -> str:
    """
    Validate an invoice with pydantic and return JSON text for the billing API.
    Input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values are UTC)
      - lines (list of {"sku": str, "quantity": int >= 1, "unit_price": decimal >= 0 given as str/int/float})
    Output JSON object:
      - number
      - issued_at formatted "YYYY-MM-DDTHH:MM:SSZ" in UTC
      - lines (each with sku, quantity, unit_price as string with exactly two decimals)
      - total (sum of quantity * unit_price, string with two decimals)
    Raises ValueError for invalid input.
    """
    try:
        invoice = Invoice.model_validate(data)
    except ValidationError as e:
        raise ValueError(e) from e

    # Format issued_at as UTC ISO8601 with trailing Z, second precision
    issued_at_utc = invoice.issued_at.astimezone(timezone.utc).replace(microsecond=0)
    issued_at_str = issued_at_utc.isoformat().replace('+00:00', 'Z')

    # Prepare lines with unit_price as string with exactly two decimals
    lines_out = []
    total = Decimal('0')
    for line in invoice.lines:
        # Quantize unit_price to two decimals (round down)
        unit_price_2dp = line.unit_price.quantize(Decimal('0.01'), rounding=ROUND_DOWN)
        lines_out.append({
            'sku': line.sku,
            'quantity': line.quantity,
            'unit_price': f"{unit_price_2dp:.2f}",
        })
        total += line.unit_price * line.quantity

    # Quantize total to two decimals (round down)
    total_2dp = total.quantize(Decimal('0.01'), rounding=ROUND_DOWN)

    out = {
        'number': invoice.number,
        'issued_at': issued_at_str,
        'lines': lines_out,
        'total': f"{total_2dp:.2f}",
    }

    return json.dumps(out, separators=(',', ':'))

import re
from typing import Any
from pydantic import BaseModel, Field, ValidationError, field_validator, model_validator


class PhoneNumber:
    """
    Phone number in international form: '+' followed by 8-15 digits.
    Spaces, dots, dashes and parentheses in the input are ignored.
    """

    def __init__(self, value: str) -> None:
        # Normalize input by removing spaces, dots, dashes, parentheses
        if not isinstance(value, str):
            raise ValueError("Phone number must be a string")
        normalized = re.sub(r"[ .\-\(\)]", "", value)
        if not re.fullmatch(r"\+[0-9]{8,15}", normalized):
            raise ValueError("Phone number must be '+' followed by 8-15 digits")
        self.value = normalized

    @classmethod
    def validate(cls, value: Any) -> "PhoneNumber":
        # This method is used by pydantic for validation
        if isinstance(value, cls):
            return value
        try:
            return cls(value)
        except ValueError as e:
            raise ValueError(str(e))

    def __repr__(self) -> str:
        return f"PhoneNumber({self.value!r})"

    def __str__(self) -> str:
        return self.value

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, PhoneNumber):
            return False
        return self.value == other.value


class SignupPayload(BaseModel):
    username: str = Field(...)
    email: str = Field(...)
    phone: PhoneNumber = Field(...)
    password: str = Field(...)
    password_confirm: str = Field(...)

    model_config = {
        "from_attributes": True,
    }

    @field_validator("username")
    @classmethod
    def username_pattern(cls, v: str) -> str:
        if not isinstance(v, str):
            raise ValueError("username must be a string")
        if not re.fullmatch(r"^[a-z0-9_]{3,20}$", v):
            raise ValueError("username must match ^[a-z0-9_]{3,20}$")
        return v

    @field_validator("email")
    @classmethod
    def email_validate(cls, v: str) -> str:
        if not isinstance(v, str):
            raise ValueError("email must be a string")
        v_stripped = v.strip().lower()
        if "@" not in v_stripped:
            raise ValueError("email must contain '@'")
        return v_stripped

    @field_validator("password")
    @classmethod
    def password_length(cls, v: str) -> str:
        if not isinstance(v, str):
            raise ValueError("password must be a string")
        if len(v) < 8:
            raise ValueError("password must be at least 8 characters")
        return v

    @model_validator(mode="after")
    @classmethod
    def passwords_match(cls, values: "SignupPayload") -> "SignupPayload":
        if values.password != values.password_confirm:
            raise ValueError("password_confirm does not match password")
        return values


def validate_signup(data: dict) -> dict:
    """
    Validate a sign-up payload with pydantic.
    Fields:
      - username: ^[a-z0-9_]{3,20}$
      - email: contains '@', returned stripped and lower-cased
      - phone: spaces, dots, dashes, parentheses removed, then '+' followed by 8-15 digits
      - password: at least 8 characters
      - password_confirm: must equal password
    Returns dict with keys: username, email, phone (compact string)
    Raises ValueError (ValidationError) for missing or invalid fields.
    """
    validated = SignupPayload.model_validate(data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": str(validated.phone),
    }
